import heapq

def match(orders):
    book = {}  # id -> dict(qty, active, price, time, side)
    buy_heap = []   # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)
    trades = []
    time_counter = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        time_counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                price_top, t, rid = sell_heap[0]
                r = book.get(rid)
                if r is None or not r['active'] or r['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ == 'market' or price >= price_top:
                    heapq.heappop(sell_heap)
                    trade_qty = min(remaining, r['qty'])
                    trades.append([oid, rid, price_top, trade_qty])
                    remaining -= trade_qty
                    r['qty'] -= trade_qty
                    if r['qty'] > 0:
                        heapq.heappush(sell_heap, (price_top, t, rid))
                    else:
                        r['active'] = False
                else:
                    break

            if typ == 'limit' and remaining > 0:
                book[oid] = {'qty': remaining, 'active': True, 'price': price,
                             'time': time_counter, 'side': side}
                heapq.heappush(buy_heap, (-price, time_counter, oid))

        else:  # side == 'sell'
            while remaining > 0 and buy_heap:
                neg_price, t, rid = buy_heap[0]
                price_top = -neg_price
                r = book.get(rid)
                if r is None or not r['active'] or r['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ == 'market' or price <= price_top:
                    heapq.heappop(buy_heap)
                    trade_qty = min(remaining, r['qty'])
                    trades.append([rid, oid, price_top, trade_qty])
                    remaining -= trade_qty
                    r['qty'] -= trade_qty
                    if r['qty'] > 0:
                        heapq.heappush(buy_heap, (neg_price, t, rid))
                    else:
                        r['active'] = False
                else:
                    break

            if typ == 'limit' and remaining > 0:
                book[oid] = {'qty': remaining, 'active': True, 'price': price,
                             'time': time_counter, 'side': side}
                heapq.heappush(sell_heap, (price, time_counter, oid))

    return trades

